import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './AuthContext';
import { AdminRoute, ProtectedRoute, PublicRoute } from './ProtectedRoute';

// Public pages
import LoginPage from './LoginPage';
import UnauthorizedPage from './UnauthorizedPage';

// Admin pages
import AdminHomePage from './AdminHomePage';
import AssignWork from './AssignWork';
import AdminViewWork from './AdminViewWork';
import CompanyProfiles from './CompanyProfiles';
import InspectorProfiles from './InspectorProfiles';
import ProfileTab from './ProfileTab';

// Worker pages
import HomePage from './HomePage';
import InspectorAssignedWork from './InspectorAssignedWork';
import InspectorBillingPage from './InspectorBillingPage';

function App() {
  return (
    <Router>
      <AuthProvider>
        <Routes>
          {/* Public Routes */}
          <Route element={<PublicRoute />}>
            <Route path="/login" element={<LoginPage />} />
            <Route path="/" element={<Navigate to="/login" replace />} />
          </Route>

          <Route path="/unauthorized" element={<UnauthorizedPage />} />

          {/* Admin Routes */}
          <Route element={<AdminRoute />}>
            <Route path="/admin" element={<AdminHomePage />}>
              <Route index element={<div>Welcome to the Admin Dashboard</div>} />
              <Route path="assign" element={<AssignWork />} />
              <Route path="viewwork" element={<AdminViewWork />} />
              <Route path="companies" element={<CompanyProfiles />} />
              <Route path="inspectors" element={<InspectorProfiles />} />
              <Route path="profile" element={<ProfileTab />} />
              <Route path="*" element={<Navigate to="/admin" replace />} />
            </Route>
          </Route>

          {/* Worker Routes */}
          <Route element={<ProtectedRoute />}>
            <Route path="/worker" element={<HomePage />}>
              <Route index element={<div>Welcome to the Worker Dashboard</div>} />
              <Route path="assigned" element={<InspectorAssignedWork />} />
              <Route path="billing" element={<InspectorBillingPage />} />
              <Route path="profile" element={<ProfileTab />} />
              <Route path="*" element={<Navigate to="/worker" replace />} />
            </Route>
          </Route>

          {/* Catch All Route */}
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </AuthProvider>
    </Router>
  );
}

export default App;
